   470  identify_http_path(struct lwan_request *request, char *buffer)
   471  {
   472      struct lwan_request_parser_helper *helper = request->helper;
   473      static const size_t minimal_request_line_len = sizeof("/ HTTP/1.0") - 1;
   474      char *space, *end_of_line;
   475      ptrdiff_t end_len;
   476
   477      if (UNLIKELY(*buffer != '/'))
   478          return NULL;
   479
   480      end_len = buffer - helper->buffer->value;
   481      if (UNLIKELY((size_t)end_len >= helper->buffer->len))
   482          return NULL;
   483
   484      end_of_line = memchr(buffer, '\r', helper->buffer->len - (size_t)end_len);
   485      if (UNLIKELY(!end_of_line))
   486          return NULL;
   487      if (UNLIKELY((size_t)(end_of_line - buffer) < minimal_request_line_len))
   488          return NULL;
   489      *end_of_line = '\0';
   490
   491      space = end_of_line - sizeof("HTTP/X.X");
   492
   493      request->url.value = buffer;
   494      request->url.len = (size_t)(space - buffer);
   495      parse_fragment_and_query(request, space);
   496      request->original_url = request->url;
   497
   498      *space++ = '\0';
   499
   500      STRING_SWITCH_LARGE(space) {
   501      case MULTICHAR_CONSTANT_LARGE('H','T','T','P','/','1','.','0'):
   502          request->flags |= REQUEST_IS_HTTP_1_0;
   503          break;
   504      case MULTICHAR_CONSTANT_LARGE('H','T','T','P','/','1','.','1'):
   505          break;
   506      default:
   507          return NULL;
   508      }
   509
   510      return end_of_line + 1;
   511  }
