  1099  static enum lwan_http_status read_post_data(struct lwan_request *request)
  1100  {
  1101      struct lwan_request_parser_helper *helper = request->helper;
  1102      /* Holy indirection, Batman! */
  1103      struct lwan_config *config = &request->conn->thread->lwan->config;
  1104      const size_t max_post_data_size = config->max_post_data_size;
  1105      char *new_buffer;
  1106      long parsed_size;
  1107
  1108      if (UNLIKELY(!helper->content_length.value))
  1109          return HTTP_BAD_REQUEST;
  1110      parsed_size = parse_long(helper->content_length.value, -1);
  1111      if (UNLIKELY(parsed_size < 0))
  1112          return HTTP_BAD_REQUEST;
  1113      if (UNLIKELY(parsed_size >= (long)max_post_data_size))
  1114          return HTTP_TOO_LARGE;
  1115
  1116      size_t post_data_size = (size_t)parsed_size;
  1117      size_t have;
  1118      if (!helper->next_request) {
  1119          have = 0;
  1120      } else {
  1121          char *buffer_end = helper->buffer->value + helper->buffer->len;
  1122          have = (size_t)(ptrdiff_t)(buffer_end - helper->next_request);
  1123
  1124          if (have >= post_data_size) {
  1125              helper->post_data.value = helper->next_request;
  1126              helper->post_data.len = post_data_size;
  1127              helper->next_request += post_data_size;
  1128              return HTTP_OK;
  1129          }
  1130      }
  1131
  1132      new_buffer = alloc_post_buffer(request->conn->coro, post_data_size + 1,
  1133                                     config->allow_post_temp_file);
  1134      if (UNLIKELY(!new_buffer))
  1135          return HTTP_INTERNAL_ERROR;
  1136
  1137      helper->post_data.value = new_buffer;
  1138      helper->post_data.len = post_data_size;
  1139      if (have)
  1140          new_buffer = mempcpy(new_buffer, helper->next_request, have);
  1141      helper->next_request = NULL;
  1142
  1143      helper->error_when_time = time(NULL) + config->keep_alive_timeout;
  1144      helper->error_when_n_packets = calculate_n_packets(post_data_size);
